INSERT INTO "battle" ("id", "slug", "author_id", "title", "context", "category_id", "tags", "deadline", "created_at") VALUES
  ('ask_m_refund', 'JD87MUsS', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Getting a $3k tax refund. Pay down my card or finally take a trip?', NULL, 'other', '{"askingPreset":"m_refund"}'::jsonb, now() + interval '365 days', now() - interval '22 hours'),
  ('ask_m_grouptrip', 'sETPtTaF', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Do I tell my friends I can''t afford the group trip, or just put it on my card?', NULL, 'other', '{"askingPreset":"m_grouptrip"}'::jsonb, now() + interval '365 days', now() - interval '28 hours'),
  ('ask_m_rent', 'dStf4MgM', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Rent''s going up $200 a month. Stay or move?', 'I love my place but moving isn''t cheap either.', 'other', '{"askingPreset":"m_rent"}'::jsonb, now() + interval '365 days', now() - interval '38 hours'),
  ('ask_m_brother', 'cvbDresq', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'My brother asked to borrow $1,500. Lend it or say no?', 'He paid me back last time. Eventually.', 'other', '{"askingPreset":"m_brother"}'::jsonb, now() + interval '365 days', now() - interval '37 hours'),
  ('ask_m_blackfriday', 'vARpSKGe', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Buy the new phone on Black Friday or wait for it to drop more?', NULL, 'other', '{"askingPreset":"m_blackfriday"}'::jsonb, now() + interval '365 days', now() - interval '25 hours'),
  ('ask_m_split', 'KP2sydSB', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Split the dinner bill evenly or just pay for what I ordered?', 'I had a salad. They each had three cocktails.', 'other', '{"askingPreset":"m_split"}'::jsonb, now() + interval '365 days', now() - interval '5 hours'),
  ('ask_m_house', 'rccyDnjH', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Save for a house or put the money in the market?', NULL, 'other', '{"askingPreset":"m_house"}'::jsonb, now() + interval '365 days', now() - interval '5 hours'),
  ('ask_m_gym', 'MELrsDLg', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Is a $90 gym membership worth it if I only go twice a week?', NULL, 'other', '{"askingPreset":"m_gym"}'::jsonb, now() + interval '365 days', now() - interval '38 hours'),
  ('ask_d_text_him', '2jdCfV2C', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'He hasn''t texted back in two days. Text again or wait?', NULL, 'other', '{"askingPreset":"d_text_him"}'::jsonb, now() + interval '365 days', now() - interval '34 hours'),
  ('ask_d_text_her', 'pkG7FCum', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'She hasn''t texted back in two days. Text again or wait?', NULL, 'other', '{"askingPreset":"d_text_her"}'::jsonb, now() + interval '365 days', now() - interval '38 hours'),
  ('ask_d_second', 'jT9iAg9d', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'First date was just ok. Go on a second one?', NULL, 'other', '{"askingPreset":"d_second"}'::jsonb, now() + interval '365 days', now() - interval '12 hours'),
  ('ask_d_thanksgiving', 'XvNuynNz', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Is it too soon to bring him home for Thanksgiving?', 'We''ve been dating three months.', 'other', '{"askingPreset":"d_thanksgiving"}'::jsonb, now() + interval '365 days', now() - interval '16 hours'),
  ('ask_d_apps', 'UifTpaXP', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Delete the dating apps or give it one more month?', NULL, 'other', '{"askingPreset":"d_apps"}'::jsonb, now() + interval '365 days', now() - interval '19 hours'),
